-- Orders and net revenue per variant of the experiences shown on a Vatican (CE 189) page or matched to its clusters,
-- 30 Jul to 27 Oct 2026, all channels and paid search alone.
SELECT
    experience_id,
    variant_id,
    COUNT(*) AS count_orders,
    SUM(amount_revenue_usd) AS sum_revenue_usd,
    COUNTIF(channel_grouping = 'Paid') AS count_paid_orders

FROM `headout-analytics.analytics_reporting.fct_orders_lambda`

WHERE created_at >= TIMESTAMP('2026-07-30')
      AND created_at < TIMESTAMP('2026-10-28')
      AND experience_id IN UNNEST(SPLIT('3063,3137,3161,3166,3225,3228,3241,3361,3383,3725,3832,3853,3865,3876,3937,4019,6706,6707,6730,6732,6796,7022,7023,7422,7451,7464,7491,7761,7818,7827,7953,7955,7967,7968,7969,7971,7998,8846,8847,9092,9264,9267,9378,9379,9682,9910,9993,10253,10424,10479,10480,10644,10757,15084,15143,15144,15248,15249,15315,15414,15436,15438,15487,15839,15847,15856,15947,16135,16466,16551,16552,17798,18300,20032,20082,20195,25598,28530,28867,28869,28870,29116,29277,29998,31786,32197,33032,36101,36212,36265,36297,36641,36702,38585,39151,39152,42091,42093,42095,42741,42841,42842,43592,45695,46090,47039,47113,47114,47134,48055,48477,48825,50331,53876,54121,54334,54814,56096,56793,57134,57182,57897,58104,58636,59617,59961,59995,60100'))
      AND order_status IN ('Completed', 'Partially Completed', 'Pending')

GROUP BY 1, 2
